"""
Code emitters for OA type generation.
Generates C++ header and implementation files from type schemas.
"""
from tools.gen.type.schema import EnumDef, StructDef, TypeSchema


GEN_HEADER = (
 "// AUTO-GENERATED by tools/gen/type/generate.py — DO NOT EDIT.\n"
 "// Source of truth: tools/gen/type/schema/{schema_name}.\n"
 "// Regenerate via: python3 tools/gen/type/generate.py --live\n"
)


def camelName(name: str) -> str:
	return name[:1].lower() + name[1:]


def serializedName(value) -> str:
	return value.serializedName or value.name


def emitEnumHeader(enumDef: EnumDef, namespace: str) -> str:
	"""Emit enum class declaration for header."""
	lines = [f"enum class {enumDef.name} : {enumDef.underlyingType} {{"]

	for val in enumDef.values:
		if val.comment:
			lines.append(f"\t{val.name} = {val.value if val.value is not None else ''},  // {val.comment}")
		else:
			if val.value is not None:
				lines.append(f"\t{val.name} = {val.value},")
			else:
				lines.append(f"\t{val.name},")

	lines.append("};")

	# Enum conversions are header-complete so generated types never depend on an
	# untracked or uncompiled implementation file.
	if enumDef.generateTostring:
		lines.append(emitEnumTostring(enumDef).rstrip())

	if enumDef.generateFromstring:
		lines.append(emitEnumFromstring(enumDef).rstrip())

	lines.append("")
	return "\n".join(lines)


def emitEnumTostring(enumDef: EnumDef) -> str:
	"""Emit ToString implementation for enum."""
	lines = [
	 f"[[nodiscard]] constexpr const char* "
	 f"{camelName(enumDef.name)}ToString({enumDef.name} inType) noexcept {{"
	]
	lines.append("\tswitch (inType) {")

	for val in enumDef.values:
		lines.append(
		 f"\t\tcase {enumDef.name}::{val.name}: "
		 f"return \"{serializedName(val)}\";"
		)

	lines.append("\t\tdefault: return \"unknown\";")
	lines.append("\t}")
	lines.append("}")
	lines.append("")
	return "\n".join(lines)


def emitEnumFromstring(enumDef: EnumDef) -> str:
	"""Emit FromString implementation for enum using the OA C-string primitive."""
	defaultValue = f"{enumDef.name}::{enumDef.values[0].name}"
	lines = [
	 f"[[nodiscard]] inline {enumDef.name} "
	 f"{camelName(enumDef.name)}FromString(const char* inString) noexcept {{"
	]
	lines.append(f"\tif (inString == nullptr) return {defaultValue};")

	for val in enumDef.values:
		lines.append(
			 f"\tif (oa::strcmp(inString, \"{serializedName(val)}\") == 0) "
		 f"return {enumDef.name}::{val.name};"
		)

	lines.append(f"\treturn {defaultValue};")
	lines.append("}")
	lines.append("")
	return "\n".join(lines)


def emitStructHeader(structDef: StructDef, namespace: str) -> str:
	"""Emit struct declaration for header."""
	lines = [f"struct {structDef.name} {{"]

	for field in structDef.fields:
		declaration = f"\t{field.type} {field.name}"
		if field.default:
			declaration += f" = {field.default}"
		declaration += ";"
		if field.comment:
			declaration += f"  // {field.comment}"
		lines.append(declaration)

	lines.append("};")
	lines.append("")
	return "\n".join(lines)


def emitHeaderFile(schema: TypeSchema, schemaName: str) -> str:
	"""Emit complete header file."""
	lines = [GEN_HEADER.format(schema_name=schemaName)]
	lines.append(f"#pragma once")
	lines.append("")
	lines.append("#include <oa/core/types.h>")
	if any(enum.generateFromstring for enum in schema.enums):
		lines.append("#include <oa/core/std/cString.h>")
	lines.append("")

	lines.append(f"namespace {schema.namespace} {{")
	lines.append("")

	for enum in schema.enums:
		lines.append(emitEnumHeader(enum, schema.namespace))

	for struct in schema.structs:
		lines.append(emitStructHeader(struct, schema.namespace))

	lines.append(f"}} // namespace {schema.namespace}")
	lines.append("")

	return "\n".join(lines)


def emitCppFile(schema: TypeSchema, schemaName: str) -> str:
	"""Emit complete implementation file."""
	lines = [GEN_HEADER.format(schema_name=schemaName)]

	# Include the generated header
	domain = schema.domain
	headerPath = f"<oa/{domain.lower()}/type.gen.h>"
	lines.append(f"#include {headerPath}")
	lines.append("")

	return "\n".join(lines)
